#ifndef MEP_JAVA_LSP_H
#define MEP_JAVA_LSP_H

// The analysis half of mep's own Java language server (the wire half is
// java_lsp_server.cpp, the `mep-java-lsp` binary; the `java_ls` entry
// in main.cpp's kBuiltinLsp spawns it). Everything here is a pure function
// of the document text, so the whole server is testable without a client
// (java_lsp_test.cpp). Positions are 0-based lines and 0-based byte
// columns (`positionEncoding: "utf-8"`).
//
// Generated by tools/new_language.py; nix_lsp.h is the worked example of
// every function below.

#include <functional>
#include <memory>
#include <string>
#include <vector>

struct JavaLspRange {
    int line = 0, col = 0, end_line = 0, end_col = 0;
};

class JavaLspDocument;

/** @brief Parses and analyses a document; every query below runs on the result. */
std::shared_ptr<const JavaLspDocument> JavaLspAnalyze(const std::vector<std::string> &lines);

// --- Diagnostics ------------------------------------------------------------------

enum class JavaLspSeverity { Error = 1, Warning = 2, Information = 3, Hint = 4 };

struct JavaLspDiagnostic {
    JavaLspRange range;
    JavaLspSeverity severity = JavaLspSeverity::Error;
    std::string code;  // stable id: syntax-error, ...
    std::string message;
    bool unnecessary = false;  // LSP DiagnosticTag.Unnecessary
    bool deprecated = false;   // LSP DiagnosticTag.Deprecated
};

std::vector<JavaLspDiagnostic> JavaLspDiagnostics(const JavaLspDocument &doc);
/** @brief `path:line:col: severity: message [code]`, 1-based, as `--lint` prints it. */
std::string JavaLspFormatDiagnostic(const std::string &path, const JavaLspDiagnostic &d);
/** @brief Whether a diagnostic makes `--lint` exit non-zero (an error or a warning). */
bool JavaLspDiagnosticFails(const JavaLspDiagnostic &d);

// --- Completion / hover / signature help -------------------------------------------

enum class JavaLspKind {
    Text = 1, Method = 2, Function = 3, Field = 5, Variable = 6, Class = 7, Module = 9, Property = 10,
    Value = 12, Keyword = 14, Snippet = 15, Constant = 21, Struct = 22,
};

struct JavaLspCompletionItem {
    std::string label;
    std::string insert_text;
    JavaLspKind kind = JavaLspKind::Text;
    std::string detail;
    std::string documentation;
    int replace_start = 0, replace_end = 0;  // byte columns on the request's line
};

std::vector<JavaLspCompletionItem> JavaLspCompletions(const JavaLspDocument &doc, int line, int col);

struct JavaLspHoverInfo {
    bool found = false;
    std::string text;  // markdown
    JavaLspRange range;
};

/** @brief The Javadoc of the declaration the name at the cursor means, from this document only. */
JavaLspHoverInfo JavaLspHover(const JavaLspDocument &doc, int line, int col);

/**
 * @brief The name hover looks up at a position, for other files (java_lsp_javadoc.h's Find): `word`, or
 * `Qualifier.word` for `x.word` -- with x's declared type when the document declares a variable x
 * (`DataFrame x = ...` makes `df.filter` `DataFrame.filter`). With a method-type lookup (see
 * JavaLspTypeOfExpression), the receiver can be any expression whose type follows from the text:
 * `var x = new DataFrame()`, a chained call `a.select(...).sortBy`, `Data.iris().nrows`, or a call
 * continued from the line above (`    .lines(...)`).
 */
struct JavaLspDocQuery {
    bool found = false;
    std::string name;
    JavaLspRange range;
};

/** @brief The return type of method METHOD of type TYPE (a simple or qualified name), or "" when unknown. */
using JavaLspMethodType = std::function<std::string(const std::string &type, const std::string &method)>;

JavaLspDocQuery JavaLspDocQueryAt(const JavaLspDocument &doc, int line, int col);
JavaLspDocQuery JavaLspDocQueryAt(const JavaLspDocument &doc, int line, int col, const JavaLspMethodType &method_type);

/**
 * @brief The type of Java expression EXPR in a document of LINES, without a compiler, or "": `new T(...)`
 * is T, a capitalised name is a type, a variable has its declared type (`var x = e` the type of e), and
 * `recv.m(...)` is what METHOD_TYPE says m of recv's type returns. Type arguments are dropped.
 */
std::string JavaLspTypeOfExpression(const std::vector<std::string> &lines, const std::string &expr,
                                    const JavaLspMethodType &method_type);

/**
 * @brief The return type in method NAME's declaration header SIGNATURE (`public static DataFrame iris()`
 * gives `DataFrame`, `List<String> columns()` gives `List`), or "" when SIGNATURE declares no such method.
 */
std::string JavaLspReturnType(const std::string &signature, const std::string &name);

/** @brief The class a class declaration header extends (`public class RPlot extends Plot` gives `Plot`), or "". */
std::string JavaLspSuperclass(const std::string &signature);

/** @brief The declared type of variable NAME in LINES (`Type name =`, `Type name;`, a parameter), or "". */
std::string JavaLspTypeOfVariable(const std::vector<std::string> &lines, const std::string &name);

/** @brief The document's source text (lines joined), for java_lsp_javadoc.h's PackageRoot. */
const std::string &JavaLspText(const JavaLspDocument &doc);

struct JavaLspSignatureHelp {
    bool found = false;
    std::string label;
    std::vector<std::string> params;  // substrings of label
    std::string documentation;
    int active_param = 0;
};

JavaLspSignatureHelp JavaLspSignatureAt(const JavaLspDocument &doc, int line, int col);

// --- Navigation -------------------------------------------------------------------------

struct JavaLspLocation {
    JavaLspRange range;
};

std::vector<JavaLspLocation> JavaLspDefinition(const JavaLspDocument &doc, int line, int col);

struct JavaLspReference {
    JavaLspRange range;
    bool is_definition = false;
};

std::vector<JavaLspReference> JavaLspReferences(const JavaLspDocument &doc, int line, int col);

struct JavaLspTextEdit {
    JavaLspRange range;
    std::string new_text;
};

struct JavaLspRenameTarget {
    bool found = false;
    JavaLspRange range;
    std::string placeholder;
};

JavaLspRenameTarget JavaLspPrepareRename(const JavaLspDocument &doc, int line, int col);
std::vector<JavaLspTextEdit> JavaLspRename(const JavaLspDocument &doc, int line, int col,
                                               const std::string &new_name, std::string *error);

// --- Outline / folding --------------------------------------------------------------------

enum class JavaLspSymbolKind {
    File = 1, Module = 2, Namespace = 3, Class = 5, Method = 6, Property = 7, Field = 8, Function = 12,
    Variable = 13, Constant = 14, String = 15, Number = 16, Boolean = 17, Array = 18, Object = 19, Key = 20,
    Null = 21,
};

struct JavaLspSymbol {
    std::string name;
    std::string detail;
    JavaLspSymbolKind kind = JavaLspSymbolKind::Variable;
    JavaLspRange range;
    JavaLspRange sel_range;
    int parent = -1;
};

std::vector<JavaLspSymbol> JavaLspSymbols(const JavaLspDocument &doc);

struct JavaLspFold {
    int start_line = 0, end_line = 0;
    std::string kind;  // "" or "comment"
};

std::vector<JavaLspFold> JavaLspFolds(const JavaLspDocument &doc);

// --- Formatting ------------------------------------------------------------------------------

/** @brief The formatter as one edit over the changed lines; none when already formatted. */
std::vector<JavaLspTextEdit> JavaLspFormat(const std::vector<std::string> &lines, int width, std::string *error);

#endif  // MEP_JAVA_LSP_H
